def solve9(gi):
    g=[r[:] for r in gi]
    H,W=len(gi),len(gi[0])
    bg=Counter(x for r in gi for x in r).most_common(1)[0][0]
    pts=[(r,c) for r in range(H) for c in range(W) if gi[r][c]!=bg]
    r0,r1=min(p[0] for p in pts),max(p[0] for p in pts); c0,c1=min(p[1] for p in pts),max(p[1] for p in pts)
    def paint(r,c):
        if g[r][c]==bg: g[r][c]=2
    for c in range(c0,c1+1): paint(r0,c); paint(r1,c)
    for r in range(r0,r1+1): paint(r,c0); paint(r,c1)
    for r in range(H):
        js=sorted(j for j in range(W) if gi[r][j]!=bg)
        # gaps between consecutive markers <=2
        for a,b in zip(js,js[1:]):
            L=b-a-1
            if L<=2:
                for j in range(a+1,b): paint(r,j)
        # gaps between marker and bbox edge (wall) <=2
        if js and r0<=r<=r1:
            for j in (js[0],js[-1]):
                if j>c0:
                    for k in range(j+1,c1+1): paint(r,k)
                if j<c1:
                    for k in range(c0,j): paint(r,k)
    return g
